[
  {
    "name": "price_rel_user90",
    "idea": "Ratio of the candidate's 90-day mean price to the user's 90-day median paid price, so the model can rank items in the user's own price band instead of learning it from two separate absolute prices.",
    "level": "pair",
    "sql": "WITH ip AS (SELECT article_id, AVG(price) AS p FROM tx WHERE t_dat >= DATE '{A}' - INTERVAL 90 DAY GROUP BY article_id), up AS (SELECT t.customer_id, MEDIAN(t.price) AS p FROM tx t JOIN users u ON t.customer_id = u.customer_id WHERE t.t_dat >= DATE '{A}' - INTERVAL 90 DAY GROUP BY t.customer_id) SELECT c.customer_id, c.article_id, ip.p / up.p AS ag_price_rel90 FROM cand c JOIN ip ON ip.article_id = c.article_id JOIN up ON up.customer_id = c.customer_id WHERE up.p > 0;"
  },
  {
    "name": "type_recency365",
    "idea": "Days since the user last bought any article of the candidate's product_type_no within 365 days, a recency signal for the category that the 28-day affinity counts do not give.",
    "level": "pair",
    "sql": "WITH ut AS (SELECT t.customer_id, a.product_type_no, MAX(t.t_dat) AS d FROM tx t JOIN users u ON t.customer_id = u.customer_id JOIN articles a ON t.article_id = a.article_id WHERE t.t_dat >= DATE '{A}' - INTERVAL 365 DAY GROUP BY t.customer_id, a.product_type_no) SELECT c.customer_id, c.article_id, COALESCE(date_diff('day', ut.d, DATE '{A}'), 366) AS ag_type_recency365 FROM cand c LEFT JOIN articles a ON a.article_id = c.article_id LEFT JOIN ut ON ut.customer_id = c.customer_id AND ut.product_type_no = a.product_type_no;"
  },
  {
    "name": "cobuy_confidence28",
    "idea": "Sum over the user's 28-day articles of the smoothed share of each article's buyers who also bought the candidate within the same 28 days. This customer-level association rule is normalized by source popularity, unlike the raw same-day basket count.",
    "level": "pair",
    "sql": "WITH ua AS (SELECT DISTINCT t.customer_id, t.article_id FROM tx t JOIN users u ON t.customer_id = u.customer_id WHERE t.t_dat >= DATE '{A}' - INTERVAL 28 DAY), src AS (SELECT DISTINCT article_id FROM ua), b AS (SELECT DISTINCT customer_id, article_id FROM tx WHERE t_dat >= DATE '{A}' - INTERVAL 28 DAY), nb AS (SELECT b.article_id, COUNT(*) AS n FROM b JOIN src s ON b.article_id = s.article_id GROUP BY b.article_id), co AS (SELECT x.article_id AS a1, y.article_id AS a2, COUNT(*) AS n FROM b x JOIN src s ON x.article_id = s.article_id JOIN b y ON x.customer_id = y.customer_id AND x.article_id <> y.article_id GROUP BY x.article_id, y.article_id) SELECT c.customer_id, c.article_id, COALESCE(SUM(co.n * 1.0 / (nb.n + 5)), 0) AS ag_cobuy_conf28 FROM cand c LEFT JOIN ua ON ua.customer_id = c.customer_id LEFT JOIN co ON co.a1 = ua.article_id AND co.a2 = c.article_id LEFT JOIN nb ON nb.article_id = co.a1 GROUP BY c.customer_id, c.article_id;"
  },
  {
    "name": "user_new_arrival_share90",
    "idea": "Share of the user's 90-day transaction rows on articles at most 28 days past their first sale, a novelty-seeking trait that interacts with ag_age_days to rank fresh arrivals for trend-followers.",
    "level": "customer",
    "sql": "WITH fs AS (SELECT article_id, MIN(t_dat) AS f FROM tx GROUP BY article_id), ut AS (SELECT t.customer_id, t.t_dat, fs.f FROM tx t JOIN users u ON t.customer_id = u.customer_id JOIN fs ON fs.article_id = t.article_id WHERE t.t_dat >= DATE '{A}' - INTERVAL 90 DAY) SELECT customer_id, AVG(CASE WHEN date_diff('day', f, t_dat) <= 28 THEN 1.0 ELSE 0.0 END) AS ag_u_new_share90 FROM ut GROUP BY customer_id;"
  },
  {
    "name": "code_buyers_last_year",
    "idea": "Distinct buyers of the article's product_code family in the same calendar week one year earlier ([A-364, A-357)), a seasonal prior for the target week that no recent window captures.",
    "level": "article",
    "sql": "WITH pc AS (SELECT a2.product_code, COUNT(DISTINCT t.customer_id) AS n FROM tx t JOIN articles a2 ON t.article_id = a2.article_id WHERE t.t_dat >= DATE '{A}' - INTERVAL 364 DAY AND t.t_dat < DATE '{A}' - INTERVAL 357 DAY GROUP BY a2.product_code) SELECT a.article_id, COALESCE(pc.n, 0) AS ag_code_buyers_ly FROM articles a LEFT JOIN pc ON pc.product_code = a.product_code;"
  }
]
